// coolKey identifies one (item, plugin) ledger row.
type coolKey struct {
	rowID, pluginID string
}

// failureIndex builds the lookup the worker consults for both the cooldown-skip
// (NextEligibleAt > now) and the prior-attempts read (Attempts) when computing a
// terminal cooldown. Single-instance MVP: the ledger is terminal-only and small
// (arch §4.4), so one read per item is the intended granularity.
type failureIndex map[coolKey]store.FailureRow

func buildFailureIndex(rows []store.FailureRow) failureIndex {
	idx := make(failureIndex, len(rows))
	for _, r := range rows {
		idx[coolKey{r.ItemID, r.PluginID}] = r
	}
	return idx
}

// inCooldown reports whether (item, plugin) is still inside its terminal cooldown
// (NextEligibleAt strictly after now) — derivation skips it; the dispatch skips
// it within an item's chain (arch §4.4 loop-safety).
func inCooldown(idx failureIndex, rowID, pluginID string, now time.Time) bool {
	r, ok := idx[coolKey{rowID, pluginID}]
	if !ok {
		return false
	}
	return r.NextEligibleAt.After(now)
}

// priorAttempts returns the existing ledger row's attempt count for (item, plugin),
// or 0 when no row exists (the first terminal failure for the pair).
func priorAttempts(idx failureIndex, rowID, pluginID string) int {
	if r, ok := idx[coolKey{rowID, pluginID}]; ok {
		return r.Attempts
	}
	return 0
}

// terminalCooldown computes the (attempts-to-store, cooldown-duration) for a
// terminal RecordFailure, owning the §4.4 doubling schedule in enrich (the store
// is value-agnostic). exhausted doubles ExhaustedCool per exhaustion round
// (7d -> 14d -> 28d ...), capped at CoolCap; no_data is a flat NoDataCool (30d)
// with no doubling; pack_failed (the __streams__ lane, D-10) reuses the flat
// no_data shape at the same flat cooldown — a play-time retry re-enqueues
// before eligibility, so doubling would only punish explicit retries. The
// first exhaustion (priorAttempts == 0) records the in-memory attempt budget
// (MaxAttempts) and yields ExhaustedCool; each later exhaustion increments the
// stored attempts so the round stays recoverable.
//
// The dispatch passes the runSourceRetryable attempt count as the seed for the
// FIRST round (attempts == MaxAttempts), matching the retry->ledger joint seed.
func terminalCooldown(status string, priorAttempts int, cfg QueueConfig) (storeAttempts int, cool time.Duration) {
	if status == ledgerNoData || status == ledgerPackFailed {
		// no_data / pack_failed: flat cooldown, no doubling.
		return nextAttempts(priorAttempts, cfg.MaxAttempts), cfg.NoDataCool
	}
	storeAttempts = nextAttempts(priorAttempts, cfg.MaxAttempts)
	doublings := exhaustedDoublings(priorAttempts, cfg.MaxAttempts)
	cool = cfg.ExhaustedCool
	for i := 0; i < doublings; i++ {
		cool *= 2
		if cool >= cfg.CoolCap {
			return storeAttempts, cfg.CoolCap
		}
	}
	return storeAttempts, cool
}

// explicitCooldown is the schedule for a terminal failure of an
// explicitly-triggered run (enrichment 3.4, the pack_failed shape): a flat
// NoDataCool with NO doubling — an operator retry must never be punished by
// growth, however many times they retry (Open Question 3). Attempts still
// advance so the round stays recoverable and auditable.
func explicitCooldown(priorAttempts, maxAttempts int, cfg QueueConfig) (storeAttempts int, cool time.Duration) {
	return nextAttempts(priorAttempts, maxAttempts), cfg.NoDataCool
}

// nextAttempts is the attempt count written on a terminal RecordFailure: the
// in-memory budget on the first exhaustion (priorAttempts == 0), incremented
// thereafter so each round is distinguishable from the row.
func nextAttempts(priorAttempts, maxAttempts int) int {
	if priorAttempts == 0 {
		return maxAttempts
	}
	return priorAttempts + 1
}

// exhaustedDoublings maps the prior row's attempts to the number of cooldown
// doublings to apply. No prior row -> 0 doublings (round 1 = ExhaustedCool);
// a prior row -> the exhaustion round beyond the first. The attempts column
// starts at MaxAttempts on round 1 and increments by 1 per round.
func exhaustedDoublings(priorAttempts, maxAttempts int) int {
	if priorAttempts == 0 {
		return 0
	}
	rounds := priorAttempts - maxAttempts + 1 // round 2 onward
	if rounds < 1 {
		return 1
	}
	return rounds
}

// reconstructBase rebuilds the per-row *scannerv1.IdentifyResult the chain's Match
// step consumes, FROM THE PERSISTED DOCUMENT (D-Q2 / S7): Parsed is read out of
// doc["parsed"]; no re-probe of the file. tv-parser reads only the parsed Struct
// (relative_path/stem), which a freshly scanned item carries, so a minimal base
// suffices. B3 may re-Identify if a source needs richer base. A missing/empty
// parsed yields an empty Struct (downstream pathFromParsed handles nil/empty).
//
// When the document carries a probe JSON (doc["ffprobe"], stamped by scan), the
// reported duration is surfaced to the chain as a well-known parsed fact,
// probe_duration_seconds (serials-library D3: a frame-grab source clamps its
// seek to a fraction of the probe-reported duration so short files still yield
// a frame). The fact is advisory — sources that never read it are unaffected,
// and a missing/unparseable probe simply leaves it absent.
func reconstructBase(doc map[string]any) *scannerv1.IdentifyResult {
	st, err := toStruct(doc["parsed"]) // nil -> &structpb.Struct{} (empty)
	if st == nil {
		st = &structpb.Struct{}
	}
	_ = err
	if dur, ok := probeDuration(doc["ffprobe"]); ok {
		if st.Fields == nil {
			st.Fields = make(map[string]*structpb.Value, 1)
		}
		st.Fields["probe_duration_seconds"] = structpb.NewNumberValue(dur)
	}
	return &scannerv1.IdentifyResult{Parsed: st}
}

// probeDuration extracts the probe-reported duration in seconds from the
// persisted ffprobe JSON ({"format": {"duration": "<seconds>"}} — verbatim
// ffprobe output carries it as a JSON string). The document view differs by
// path: a store round-trip decodes it to a map, a freshly assembled (un-
// persisted) document carries json.RawMessage — both are accepted. Absent on a
// directory-backed row, an unparseable probe, or a non-numeric duration.
func probeDuration(raw any) (float64, bool) {
	var durStr string
	switch v := raw.(type) {
	case map[string]any: // decoded document (decodeDoc)
		format, ok := v["format"].(map[string]any)
		if !ok {
			return 0, false
		}
		durStr, ok = format["duration"].(string)
		if !ok {
			if n, isNum := format["duration"].(float64); isNum {
				return n, n > 0
			}
			return 0, false
		}
	case json.RawMessage:
		durStr = rawDurationString(v)
	case []byte:
		durStr = rawDurationString(v)
	case string:
		durStr = rawDurationString([]byte(v))
	default:
		return 0, false
	}
	d, err := strconv.ParseFloat(durStr, 64)
	if err != nil || d <= 0 {
		return 0, false
	}
	return d, true
}

// rawDurationString pulls format.duration out of a raw ffprobe JSON payload.
// Empty when the payload is unparseable or the key is absent.
func rawDurationString(b []byte) string {
	var probe struct {
		Format struct {
			Duration string `json:"duration"`
		} `json:"format"`
	}
	if err := json.Unmarshal(b, &probe); err != nil {
		return ""
	}
	return probe.Format.Duration
}

// toStruct normalizes the persisted parsed value into a *structpb.Struct. A
// document round-tripped through the store carries parsed as map[string]any; a
// freshly assembled (un-persisted) document carries it as json.RawMessage. Both
// are accepted so the worker and the in-memory Enrich path share reconstruction.
func toStruct(v any) (*structpb.Struct, error) {
	switch p := v.(type) {
	case nil:
		return &structpb.Struct{}, nil
	case map[string]any:
		return structpb.NewStruct(p)
	case json.RawMessage:
		st := &structpb.Struct{}
		if err := st.UnmarshalJSON(p); err != nil {
			return nil, fmt.Errorf("enrich: parsed raw json: %w", err)
		}
		return st, nil
	case []byte:
		st := &structpb.Struct{}
		if err := st.UnmarshalJSON(p); err != nil {
			return nil, fmt.Errorf("enrich: parsed bytes: %w", err)
		}
		return st, nil
	}
	return nil, fmt.Errorf("enrich: parsed is %T, not a struct", v)
}

// decodeDoc unmarshals the persisted opaque document into a mutable map. A missing
// or unparseable document yields an empty map (the worker still advances the item
// through its chain; sources write into the fresh document).
//
// _stages is normalized to the in-memory form here: encoding/json decodes a JSON
// array of objects into []any (each element map[string]any), but appendStage
// (enrich.go) and attemptedNoWork read _stages as []map[string]any. Without this
// coercion a store round-trip (persistRow marshals -> decodeDoc unmarshals) silently
// breaks both unchecked assertions — appendStage would drop prior history (data loss)
// and attemptedNoWork could not observe a prior-pass stage. Normalizing once at the
// decode boundary keeps both readers correct across every re-derive. A no-op when
// _stages is absent or already []map[string]any (the in-memory / sync path).
func decodeDoc(raw json.RawMessage) map[string]any {
	if len(raw) == 0 {
		return map[string]any{}
	}
	var doc map[string]any
	if err := json.Unmarshal(raw, &doc); err != nil {
		return map[string]any{}
	}
	normalizeStages(doc)
	return doc
}

// normalizeStages coerces doc["_stages"] from the []any form encoding/json produces
// into the []map[string]any form appendStage/attemptedNoWork consume, so the _stages
// audit history survives a store round-trip. A no-op when _stages is missing, already
// []map[string]any, or some other type; non-object elements are dropped defensively
// (appendStage only ever writes map[string]any entries, so a well-formed doc has none).
func normalizeStages(doc map[string]any) {
	raw, ok := doc["_stages"]
	if !ok {
		return
	}
	arr, ok := raw.([]any)
	if !ok {
		return // already []map[string]any (in-memory form), or absent — leave as-is.
	}
	out := make([]map[string]any, 0, len(arr))
	for _, e := range arr {
		if m, ok := e.(map[string]any); ok {
			out = append(out, m)
		}
	}
	doc["_stages"] = out
}

// driveResult carries the per-item chain outcome back to the worker driver.
type driveResult struct {
	begun     bool  // at least one engaging source ran (state left pending-or-beyond)
	succeeded int   // sources that committed a namespace
	hardAbort bool  // ctx cancelled mid-chain (the only hard failure)
	err       error // cause on hardAbort
	// episodeRuns collects the successful source results that carried
	// ConvertResult.EpisodeTitles (episode-titles): on a series row the driver
	// routes them onto the series' episode documents after the run commits.
	episodeRuns []sourceResult
}

// driveSources runs every queueable source that still has pending work for the
// item — the module chain in Priority order (serial within the item — D8), then
// the element-attached extras in attachment order (element-pages D-4), all
// through the identical predicate, retry, and ledger path. It mutates doc +
// status and writes the ledger (RecordFailure on terminal, ClearFailure on
// success after a prior row). Soft-fail: a source's terminal failure /
// unavailable / skipped outcome never aborts the chain — only ctx.Done() does
// (INV-soft-fail). sc is the deferred-handoff scope (nil = relay disabled,
// client-relayed-fetch D4); a deferred outcome writes nothing here — the
// relayed ledger row Enqueue wrote IS the loop-safety write.
func (q *Queue) driveSources(
	ctx context.Context, mod module.Module, extras []module.MetadataSourceBinding,
	doc map[string]any, base *scannerv1.IdentifyResult,
	rowID string, idx failureIndex, status *string, sc *relayScope,
) driveResult {
	res := driveResult{}
	nowt := now()
	for _, src := range append(orderedSources(mod.MetadataSources), extras...) {
		if err := ctx.Err(); err != nil {
			res.hardAbort = true
			res.err = err
			return res
		}
		if !queueable(src) || hasNamespace(doc, src.PluginID) {
			continue
		}
		if inCooldown(idx, rowID, src.PluginID, nowt) {
			continue
		}
		sr, ledgerStatus, attempts := runSourceRetryable(ctx, q.resolve, src, mod, base, doc, q.deps.FetchGate, sc, q.cfg.MaxAttempts, q.cfg.Backoff)
		*status = advanceForSource(*status, sr.kind, &res.begun)
		appendStage(doc, sr, *status)
		q.applyOutcome(ctx, rowID, src.PluginID, idx, sr, ledgerStatus, attempts)
		if sr.kind == outcomeSucceeded && len(sr.namespace) > 0 {
			applyContribution(doc, sr)
			res.succeeded++
		}
		if sr.kind == outcomeSucceeded && len(sr.episodeTitles) > 0 {
			res.episodeRuns = append(res.episodeRuns, sr) // routed after the run commits (episode_titles.go)
		}
	}
	return res
}

// advanceForSource mirrors enrichDoc's per-source lifecycle advance: the first
// engaging source begins (new -> pending); a later engaging source after a parsed
// gap re-enters pending; a success then parses. A failure engages (begins) but
// does not advance further (furthest-valid preserved). Terminal-failures share the
// outcomeFailed kind for state purposes — they do not block settlement (a
// terminal pair in cooldown counts as "no pending work"). A DEFERRED source
// performs no transition at all: the deferred run is the item's in-flight
// state (client-relayed-fetch contract — no lifecycle change; the relayed
// ledger row is the pair's quiet-down, and the completion wake re-derives the
// pair for the consult).
func advanceForSource(status string, kind outcomeKind, begun *bool) string {
	switch kind {
	case outcomeSucceeded:
		if !*begun {
			status = advance(status, evBegin)
			*begun = true
		} else if status == statusParsed {
			status = advance(status, evBegin)
		}
		return advance(status, evParsed)
	case outcomeFailed:
		if !*begun {
			status = advance(status, evBegin)
			*begun = true
		}
	case outcomeDeferred:
		// no lifecycle transition
	}
	return status
}

// applyOutcome maps a source outcome onto the ledger (the ONLY store writes from
// the dispatch). Success-after-ledger deletes the row (reset-on-success); a
// terminal outcome writes the cooldown schedule. Skipped/unavailable/cancelled
// outcomes write nothing (INV-rare-ledger-writes).
func (q *Queue) applyOutcome(
	ctx context.Context, rowID, pluginID string, idx failureIndex,
	sr sourceResult, ledgerStatus string, attempts int,
) {
	if ledgerStatus == "" {
		if sr.kind == outcomeSucceeded && priorAttempts(idx, rowID, pluginID) > 0 {
			q.storeWrite(func() error { return q.deps.Store.ClearFailure(ctx, rowID, pluginID) }) // reset-on-success
		}
		return
	}
	prior := priorAttempts(idx, rowID, pluginID)
	storeAttempts, cool := terminalCooldown(ledgerStatus, prior, q.cfg)
	if q.takeExplicit(rowID, pluginID) { // an explicitly-triggered run cools flat, never doubled (enrichment 3.4)
		storeAttempts, cool = explicitCooldown(prior, q.cfg.MaxAttempts, q.cfg)
	}
	reason := sr.errMsg
	if reason == "" {
		reason = ledgerStatus
	}
	if sr.fetchClass != "" {
		// A fetch failure's reason carries the machine class token in the
		// relay enqueue's shape ("<class>: <text>" — the same format
		// Enqueue writes), human text alongside; redactURLs re-applied is
		// idempotent and keeps the no-keyed-URL invariant at the write
		// regardless of what the free text carries.
		reason = fmt.Sprintf("%s: %s", sr.fetchClass, redactURLs(reason))
	}
	next := now().Add(cool)
	q.storeWrite(func() error {
		return q.deps.Store.RecordFailure(ctx, rowID, pluginID, ledgerStatus, reason, storeAttempts, next)
	})
}

// allSourcesTerminal reports whether every queueable source for the item —
// chain and element-attached extras alike (element-pages D-4) — has reached a
// terminal state: done (namespace present), in-ledger-cooldown, OR
// attempted-this-run-but-produced-no-work (an unavailable/skipped _stages entry).
// When true, the item has no pending work and may settle to ready (arch §4.4). A
// source with neither a namespace, a ledger row, nor a recorded attempt still has
// genuine pending work and must not settle.
func allSourcesTerminal(idx failureIndex, mod module.Module, extras []module.MetadataSourceBinding, doc map[string]any, rowID string, nowt time.Time) bool {
	for _, src := range append(mod.MetadataSources, extras...) {
		if !queueable(src) {
			continue
		}
		if hasNamespace(doc, src.PluginID) || inCooldown(idx, rowID, src.PluginID, nowt) {
			continue
		}
		if attemptedNoWork(doc, src.PluginID) {
			continue
		}
		return false
	}
	return true
}

// attemptedNoWork reports whether the source's most-recent _stages entry records a
// terminal-non-success outcome — it ran this pass but committed no namespace and no
// terminal ledger row. The qualifying stage statuses are exactly the values
// stageStatus emits for unavailable/skipped sources (enrich.go: "unavailable",
// "skipped"): e.g. a queueable SERVER source that is not loaded in B1 (tmdb) yields
// outcomeUnavailable -> no namespace + no ledger. Treating it as terminal-at-settle
// lets the item reach ready instead of stalling at enriched forever; a later load
// re-derives it (namespace absent + not in cooldown) without regressing ready (B3
// forward-compat: reengage(ready)=ready, settle acts only on enriched). A success
// ("ok") carries a namespace; a transient-exhaustion ("failed") lands in the ledger.
func attemptedNoWork(doc map[string]any, pluginID string) bool {
	stages, _ := doc["_stages"].([]map[string]any)
	for i := len(stages) - 1; i >= 0; i-- { // most-recent entry first (appendStage appends)
		pid, _ := stages[i]["plugin_id"].(string)
		if pid != pluginID {
			continue
		}
		status, _ := stages[i]["status"].(string)
		return status == "unavailable" || status == "skipped"
	}
	return false
}
